using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.AI;

namespace Microsoft.Agents.AI;

/// <summary>
/// An <see cref="AIContextProvider"/> that gives agents the ability to maintain a persistent todo list
/// within a session.
/// </summary>
/// <remarks>
/// <para>
/// The provider exposes five tools to the agent — <c>AddTodos</c>, <c>CompleteTodos</c>, <c>RemoveTodos</c>,
/// <c>GetRemainingTodos</c>, and <c>GetAllTodos</c> — enabling an agent to plan and track progress across
/// complex, multi-step tasks.
/// </para>
/// <para>
/// State is persisted in the <see cref="AgentSession.StateBag"/> under the key <c>"TodoProvider"</c> and therefore
/// survives across multiple invocations on the same session.
/// </para>
/// </remarks>
public sealed class TodoProvider : AIContextProvider
{
    /// <summary>The key under which the todo state is stored in the session's state bag.</summary>
    private const string StateKey = "TodoProvider";

    private const string InstructionsText =
        "You have access to a persistent todo list for tracking work across this session. " +
        "Use the AddTodos tool to record tasks you plan to do, CompleteTodos to mark tasks done as you finish them, " +
        "RemoveTodos to discard tasks that are no longer relevant, GetRemainingTodos to review outstanding work, " +
        "and GetAllTodos to review the full list. Keep the list up to date as you make progress.";

    private readonly ProviderSessionState<TodoState> _sessionState;

    /// <summary>
    /// Initializes a new instance of the <see cref="TodoProvider"/> class.
    /// </summary>
    public TodoProvider()
    {
        this._sessionState = new ProviderSessionState<TodoState>(
            _ => new TodoState(),
            StateKey,
            AgentJsonUtilities.DefaultOptions);
    }

    /// <inheritdoc />
    protected override ValueTask<AIContext> ProvideAIContextAsync(InvokingContext context, CancellationToken cancellationToken = default)
    {
        var session = context.Session;

        return new ValueTask<AIContext>(new AIContext
        {
            Instructions = InstructionsText,
            Tools = this.CreateTools(session),
        });
    }

    /// <summary>
    /// Gets all todo items associated with the specified session, regardless of completion status.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved. May be <see langword="null"/>.</param>
    /// <returns>A read-only list of all todo items. Returns an empty list for a brand-new session with no prior state.</returns>
    public IReadOnlyList<TodoItem> GetAllTodos(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items;

    /// <summary>
    /// Gets the todo items associated with the specified session that have not yet been completed.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved. May be <see langword="null"/>.</param>
    /// <returns>A list of the todo items where <see cref="TodoItem.IsComplete"/> is <see langword="false"/>.</returns>
    public List<TodoItem> GetRemainingTodos(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session).Items.Where(t => !t.IsComplete).ToList();

    private IEnumerable<AITool> CreateTools(AgentSession? session)
    {
        List<TodoItem> AddTodos(List<TodoItemInput> todos)
        {
            var state = this._sessionState.GetOrInitializeState(session);
            var created = new List<TodoItem>();

            if (todos is not null)
            {
                foreach (var input in todos)
                {
                    var item = new TodoItem
                    {
                        Id = state.NextId++,
                        Title = input?.Title ?? string.Empty,
                        Description = input?.Description,
                        IsComplete = false,
                    };
                    state.Items.Add(item);
                    created.Add(item);
                }
            }

            this._sessionState.SaveState(session, state);
            return created;
        }

        int CompleteTodos(List<int> ids)
        {
            var state = this._sessionState.GetOrInitializeState(session);
            int count = 0;

            if (ids is not null)
            {
                var idSet = new HashSet<int>(ids);
                foreach (var item in state.Items.Where(t => idSet.Contains(t.Id)))
                {
                    item.IsComplete = true;
                    count++;
                }
            }

            this._sessionState.SaveState(session, state);
            return count;
        }

        int RemoveTodos(List<int> ids)
        {
            var state = this._sessionState.GetOrInitializeState(session);
            int count = 0;

            if (ids is not null)
            {
                var idSet = new HashSet<int>(ids);
                count = state.Items.RemoveAll(t => idSet.Contains(t.Id));
            }

            this._sessionState.SaveState(session, state);
            return count;
        }

        List<TodoItem> GetRemainingTodos()
            => this._sessionState.GetOrInitializeState(session).Items.Where(t => !t.IsComplete).ToList();

        List<TodoItem> GetAllTodos()
            => this._sessionState.GetOrInitializeState(session).Items.ToList();

        return
        [
            AIFunctionFactory.Create(AddTodos, new AIFunctionFactoryOptions
            {
                Name = "AddTodos",
                Description = "Adds one or more items to the todo list. Each new item is assigned a unique integer id.",
                SerializerOptions = AgentJsonUtilities.DefaultOptions,
            }),
            AIFunctionFactory.Create(CompleteTodos, new AIFunctionFactoryOptions
            {
                Name = "CompleteTodos",
                Description = "Marks the todo items with the given ids as complete. Returns the number of items that were found and completed.",
                SerializerOptions = AgentJsonUtilities.DefaultOptions,
            }),
            AIFunctionFactory.Create(RemoveTodos, new AIFunctionFactoryOptions
            {
                Name = "RemoveTodos",
                Description = "Removes the todo items with the given ids from the list. Returns the number of items removed.",
